@pytest.mark.detective
def test_registry_problems_value_2():
    """VALUE survivor — distinguishing witness (original raises ValueError: not enough values to unpack (expected 2, got 1))."""
    try:
        _result = registry_problems(
            fragments=[
                Fragment(
                    name="x",
                    version="x",
                    exposure="x",
                    requires=("x",),
                    concepts=(
                        ConceptEntry(
                            concept_id="x",
                            family="x",
                            arguments=((1,),),
                            authority="x",
                            code="x",
                            definition="x",
                            scale=(1,),
                            depends_on=("x",),
                            defined_on="x",
                        ),
                    ),
                    references=(Reference(concept_id="x", family="x", arguments=((1,),)),),
                )
            ],
            authorities={"x": ("x", "x", "x", "x")},
            exposures={"x": None},
        )
    except ValueError as _exc:
        assert str(_exc) == "not enough values to unpack (expected 2, got 1)"
    except BaseException as _exc:
        pytest.fail(f"expected ValueError, got {type(_exc).__name__}: {_exc!r}")
    else:
        pytest.fail(f"expected ValueError, but the call returned {_result!r}")
